uses as (select f.place_raw raw, f.person_id, f.fact_type, f.date_year from person_facts f join m on m.raw=f.place_raw
  union all select fam.marr_place_raw, unnest(array[fam.husband_id, fam.wife_id]), 'MARR', null from families fam join m on m.raw=fam.marr_place_raw),
rel as (
  select u.raw, u.person_id, u.person_id rel_id, 'selv' r from uses u
  union all select u.raw, u.person_id, unnest(array[f.husband_id,f.wife_id]), 'forelder' from uses u join family_children c on c.child_id=u.person_id join families f on f.family_id=c.family_id
  union all select u.raw, u.person_id, c2.child_id, 'søsken' from uses u join family_children c on c.child_id=u.person_id join family_children c2 on c2.family_id=c.family_id and c2.child_id<>u.person_id
  union all select u.raw, u.person_id, case when f.husband_id=u.person_id then f.wife_id else f.husband_id end, 'ektefelle' from uses u join families f on u.person_id in (f.husband_id,f.wife_id)
  union all select u.raw, u.person_id, c.child_id, 'barn' from uses u join families f on u.person_id in (f.husband_id,f.wife_id) join family_children c on c.family_id=f.family_id)
select json_agg(x) from (
 select m.raw,
  (select json_agg(distinct jsonb_build_object('p',u.person_id,'t',u.fact_type,'y',u.date_year)) from uses u where u.raw=m.raw) uses,
  (select json_agg(jsonb_build_object('r',rel.r,'t',f.fact_type,'y',f.date_year,'pl',a.name_display,'c',a.country,'co',coalesce(a.county,a.historical_region),'id',a.id))
     from rel join person_facts f on f.person_id=rel.rel_id and f.place_id is not null join addresses a on a.id=f.place_id where rel.raw=m.raw) ctx
 from m) x;